#include <vector>

int main() {
    std::vector<int> nums = {1, 2, 3, 4, 5, 6, 7};
    auto tail = nums | std::views::drop(5);
    for (int v : tail) std::print("{} ", v);
    nums[6] = 100;
    for (int v : tail) std::print("{} ", v);
    return 0;
}
